const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-fourier\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '2d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const duration = __narration.durationSec;
  let cursor = 0;
  const play = (actions, seconds, ease = 'linear') => {
    s.play(actions, { duration: seconds, ease });
    cursor += seconds;
  };
  const wait = seconds => { s.wait(seconds); cursor += seconds; };
  play(s.camera.to2D({ height: 10, target: [0, 0, 0] }), 0);

  // An authored, simple asymmetric radial outline, not measured data:
  // z(t) = r(t) exp(it). Each cosine supplies two complex coefficients.
  // r(t) stays positive, so the completed outline cannot self-intersect.
  const harmonics = [
    [2, 0.42, 0.3], [3, 0.34, -1.1], [4, 0.24, 0.8],
    [5, 0.18, -1.8], [6, 0.14, 0.4]
  ];
  const coefficients = [{ k: 1, radius: 1.65, phase: 0 }];
  for (const [m, amplitude, phase] of harmonics) {
    coefficients.push({ k: 1 + m, radius: amplitude / 2, phase });
    coefficients.push({ k: 1 - m, radius: amplitude / 2, phase: -phase });
  }
  const origin = [0, -0.1];
  const pointAt = angle => {
    let x = origin[0], y = origin[1];
    for (const c of coefficients) {
      x += c.radius * Math.cos(c.phase + c.k * angle);
      y += c.radius * Math.sin(c.phase + c.k * angle);
    }
    return [x, y];
  };

  const joints = [];
  const rings = [];
  let endpoint;
  function joint(i) {
    const c = coefficients[i];
    const previous = i ? coefficients[i - 1] : null;
    const center = s.circle('center-' + i, {
      radius: 0.014, fill: Color.WHITE, stroke: Color.NONE
    });
    const tip = s.circle('tip-' + i, {
      position: [c.radius, 0], radius: i === coefficients.length - 1 ? 0.055 : 0.018,
      fill: i === coefficients.length - 1 ? Color.YELLOW : Color.BLUE_A,
      stroke: Color.NONE
    });
    if (i === coefficients.length - 1) endpoint = tip;
    const ring = s.circle('epicycle-' + i, {
      radius: c.radius, fill: Color.NONE,
      stroke: { color: Color.WHITE, opacity: 0.22 }, strokeWidth: 0.012
    });
    rings.push(ring);
    const vector = s.arrow('vector-' + i, {
      points: [[0, 0], [c.radius, 0]],
      stroke: i === 0 ? Color.BLUE : Color.TEAL,
      strokeWidth: i === 0 ? 0.032 : 0.022
    });
    const children = [ring, vector, center, tip];
    if (i + 1 < coefficients.length) children.push(joint(i + 1));
    const g = s.group('joint-' + i, children, {
      position: previous ? [previous.radius, 0] : origin,
      rotation: c.phase - (previous ? previous.phase : 0)
    });
    joints[i] = g;
    s.connect(vector, center, tip, { endpoints: 'center' });
    return g;
  }
  const chain = joint(0);
  const equation = s.latex('fourier-sum', {
    tex: String.raw`z(t)=\sum_{k\in K}c_k e^{ikt}`,
    position: [0, 3.15], fontSize: 0.45, fill: Color.WHITE
  });
  const provenance = s.text('idealized-label', {
    text: '11 complex terms / idealized curve',
    position: [0, -3.5], fontSize: 0.26, fill: Color.GREY_B
  });
  play([chain.fadeIn(), equation.fadeIn(), provenance.fadeIn()], duration * 0.03, 'smooth');

  // Joint rotations, rather than endpoint tweens, preserve every vector length.
  // Each child rotates at the difference of adjacent Fourier frequencies.
  // Trace chords sample the identical coefficient sum at 480 uniform phases;
  // their subpixel deviation from the continuous endpoint is bounded by
  // sum(radius*k*k) * (2*pi/480)^2 / 8 in scene units.
  const samples = 480;
  const drawEnd = duration * 0.9;
  const drawStart = cursor;
  for (let j = 0; j < samples; j++) {
    const a0 = 2 * Math.PI * j / samples;
    const a1 = 2 * Math.PI * (j + 1) / samples;
    const p0 = pointAt(a0), p1 = pointAt(a1);
    const trace = s.line('trace-' + j, {
      points: [p0, p0], stroke: Color.YELLOW, strokeWidth: 0.035
    });
    const actions = coefficients.map((c, i) => {
      const previous = i ? coefficients[i - 1] : { phase: 0, k: 0 };
      return joints[i].rotateTo(c.phase - previous.phase + (c.k - previous.k) * a1);
    });
    actions.push(trace.morphTo({ kind: 'line', points: [p0, p1] }));
    const next = drawStart + (drawEnd - drawStart) * (j + 1) / samples;
    play(actions, next - cursor);
  }
  // Keep the entire closed trace and the exact final epicycle configuration.
  wait(duration - cursor);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-convolution\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '2d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const D = __narration.durationSec;
  let cursor = 0;
  const play = (actions, duration) => { s.play(actions, { duration, ease: 'linear' }); cursor += duration; };
  const wait = duration => { s.wait(duration); cursor += duration; };
  play(s.camera.to2D({ height: 9.4 }), 0);
  // Analytic, idealized pulses; tau and t share the horizontal scale.
  const pulses = [{ a: -2.5, b: -1, h: 1 }, { a: 0.5, b: 2, h: 0.65 }];
  const topY = 1.55, productY = -0.65, outputY = -2.85;
  const vertical = 1.03, divisions = 24;
  const g = u => Math.max(0, 1 - Math.abs(u));
  const t0 = -3.6, t1 = 3.2;
  const axis = (id, y, variable) => {
    s.line(id + '-axis', { points: [[-4.85, y], [4.85, y]], stroke: Color.GREY_B, strokeWidth: 0.016 });
    for (const x of [-4, -2, 0, 2, 4]) {
      s.line(id + '-tick-' + x, { points: [[x, y - 0.055], [x, y + 0.055]], stroke: Color.GREY_B, strokeWidth: 0.014 });
      s.text(id + '-number-' + x, { text: String(x), position: [x, y - 0.22], fontSize: 0.21, fill: Color.GREY_A });
    }
    s.latex(id + '-variable', { tex: variable, position: [5.13, y], fontSize: 0.31 });
  };
  axis('input', topY, '\\tau');
  axis('product', productY, '\\tau');
  axis('output', outputY, 't');
  s.latex('signal-key', { tex: 'f(\\tau)', position: [-3.55, 3.22], fontSize: 0.4, fill: Color.BLUE });
  s.latex('kernel-key', { tex: 'g(t-\\tau)', position: [-0.55, 3.22], fontSize: 0.4, fill: Color.YELLOW });
  s.text('model-note', { text: 'idealized pulses', position: [3.15, 3.22], fontSize: 0.27, fill: Color.GREY_A });
  s.latex('product-key', { tex: 'f(\\tau)\\,g(t-\\tau)', position: [-3.1, 0.85], fontSize: 0.36, fill: Color.TEAL });
  s.latex('convolution-rule', { tex: '(f*g)(t)=\\int f(\\tau)g(t-\\tau)\\,d\\tau', position: [-1.55, -1.48], fontSize: 0.31 });
  const areaReadout = s.latex('area-readout', {
    tex: '\\text{area }A(t)\\approx\\animnum{area}', numbers: { area: 0 },
    numberFormat: { decimals: 3, digits: 1 }, position: [2.55, 0.85], fontSize: 0.34, fill: Color.TEAL
  });
  const timeReadout = s.latex('time-readout', {
    tex: 't=\\animnum{t}', numbers: { t: t0 }, numberFormat: { decimals: 2, digits: 1 },
    position: [3.6, -1.48], fontSize: 0.31, fill: Color.YELLOW
  });
  // Each fixed-correspondence mesh cell is a trapezoid under the product.
  // Integrate those same displayed trapezoids for every output sample.
  function productData(p, t, baseline) {
    const vertices = [], points = [[p.a, baseline]], triangles = [];
    let area = 0, previous = 0;
    const dx = (p.b - p.a) / divisions;
    for (let j = 0; j <= divisions; j++) {
      const x = p.a + j * dx, value = p.h * g(t - x);
      vertices.push([x, baseline, 0], [x, baseline + vertical * value, 0]);
      points.push([x, baseline + vertical * value]);
      if (j > 0) {
        area += (previous + value) * dx / 2;
        const k = 2 * (j - 1);
        triangles.push([k, k + 2, k + 1], [k + 1, k + 2, k + 3]);
      }
      previous = value;
    }
    points.push([p.b, baseline]);
    return { vertices, triangles, points, area };
  }
  const patches = pulses.map((p, index) => {
    const upper = productData(p, t0, topY), lower = productData(p, t0, productY);
    const overlap = s.mesh('overlap-' + index, { vertices: upper.vertices, triangles: upper.triangles, shading: 'unlit', fill: Color.TEAL, opacity: 0.3, stroke: Color.NONE });
    const area = s.mesh('product-area-' + index, { vertices: lower.vertices, triangles: lower.triangles, shading: 'unlit', fill: Color.TEAL, opacity: 0.45, stroke: Color.NONE });
    const outline = s.path('product-outline-' + index, { points: lower.points, stroke: Color.TEAL, strokeWidth: 0.037, fill: Color.NONE });
    return { p, overlap, area, outline };
  });
  const signalPoints = [[-4.8, topY]];
  for (const p of pulses) signalPoints.push([p.a, topY], [p.a, topY + vertical * p.h], [p.b, topY + vertical * p.h], [p.b, topY]);
  signalPoints.push([4.8, topY]);
  s.path('two-pulse-signal', { points: signalPoints, fill: Color.NONE, stroke: Color.BLUE, strokeWidth: 0.042 });
  s.text('unit-height', { text: '1', position: [-2.77, topY + vertical], fontSize: 0.22, fill: Color.BLUE });
  s.text('second-height', { text: '0.65', position: [2.4, topY + vertical * 0.65], fontSize: 0.22, fill: Color.BLUE });
  const kernel = s.path('triangular-kernel', { points: [[-1, 0], [0, vertical], [1, 0]], stroke: Color.YELLOW, strokeWidth: 0.041, fill: Color.NONE });
  const inputMarker = s.circle('kernel-center', { radius: 0.052, fill: Color.YELLOW, stroke: Color.NONE });
  const movingKernel = s.group('moving-kernel', [kernel, inputMarker], { position: [t0, topY] });
  const markerLabel = s.latex('kernel-center-label', { tex: 't', fontSize: 0.27, fill: Color.YELLOW });
  s.attach(markerLabel, inputMarker, { offset: [0, 0.19, 0] });
  const outputMarker = s.circle('integral-marker', { position: [t0, outputY], radius: 0.068, fill: Color.TEAL, stroke: Color.NONE });
  const correspondence = s.line('input-output-correspondence', { stroke: { color: Color.YELLOW, opacity: 0.23 }, strokeWidth: 0.015 });
  s.connect(correspondence, inputMarker, outputMarker);
  wait(D * 0.075);
  const steps = 85, stepDuration = D * 0.84 / steps;
  let lastPoint = [t0, outputY];
  for (let i = 1; i <= steps; i++) {
    const t = t0 + (t1 - t0) * i / steps;
    const actions = [movingKernel.moveTo([t, topY]), timeReadout.countTo({ t })];
    let integral = 0;
    for (const patch of patches) {
      const upper = productData(patch.p, t, topY), lower = productData(patch.p, t, productY);
      integral += lower.area;
      actions.push(
        patch.overlap.morphTo({ kind: 'mesh', vertices: upper.vertices, triangles: upper.triangles, shading: 'unlit' }),
        patch.area.morphTo({ kind: 'mesh', vertices: lower.vertices, triangles: lower.triangles, shading: 'unlit' }),
        patch.outline.morphTo({ kind: 'path', points: lower.points })
      );
    }
    const nextPoint = [t, outputY + vertical * integral];
    const trace = s.line('integral-trace-' + i, { points: [lastPoint, lastPoint], stroke: Color.TEAL, strokeWidth: 0.04 });
    actions.push(trace.morphTo({ kind: 'line', points: [lastPoint, nextPoint] }), outputMarker.moveTo(nextPoint), areaReadout.countTo({ area: integral }));
    play(actions, stepDuration);
    lastPoint = nextPoint;
  }
  wait(D - cursor);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-mobius\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: '2d', orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const D = __narration.durationSec;
  let cursor = 0;
  const play = (actions, duration) => { s.play(actions, { duration, ease: 'smooth' }); cursor += duration; };
  const holdTo = t => { if (t > cursor) { s.wait(t - cursor); cursor = t; } };
  s.play(s.camera.to2D({ height: 8, target: [0, 0, 0] }), { duration: 0 });

  // This is explicitly pointwise interpolation, not a family of conformal maps.
  // Endpoint geometry, the highlighted curve and its point share one map.
  const map = ([x, y]) => {
    const den = (x + 1) * (x + 1) + y * y;
    return [(x * x + y * y - 1) / den, 2 * y / den];
  };
  const pathData = points => points.map((p, i) => `${i ? 'L' : 'M'}${p[0]} ${p[1]}`).join(' ');
  const positive = [0.004, 0.008, 0.016, 0.032, 0.064];
  for (let j = 1; j <= 80; j++) positive.push(j * 0.05 + 0.064);
  positive.push(4.5, 5, 6, 8, 12, 20, 36, 64, 128, 256);
  const all = positive.slice().reverse().map(y => -y).concat([0], positive);
  const specifications = [];
  for (let j = -6; j <= 6; j++) {
    const x = j / 2;
    if (x === -1) {
      // Separate branches at the pole; the views clip unbounded excursions.
      specifications.push({ id: `v${j}lower`, color: Color.BLUE, points: positive.slice().reverse().map(y => [x, -y]) });
      specifications.push({ id: `v${j}upper`, color: Color.BLUE, points: positive.map(y => [x, y]) });
    } else {
      specifications.push({ id: `v${j}`, color: Color.BLUE, points: all.map(y => [x, y]) });
    }
    const y = j / 2;
    if (y === 0) {
      specifications.push({ id: 'real-left', color: Color.TEAL, points: positive.slice().reverse().map(q => [-1 - q, 0]) });
      specifications.push({ id: 'real-right', color: Color.TEAL, points: positive.map(q => [-1 + q, 0]) });
    } else {
      specifications.push({ id: `h${j}`, color: Color.TEAL, points: all.map(q => [q - 1, y]) });
    }
  }
  const circlePoints = [];
  for (let k = 0; k <= 320; k++) {
    const a = -Math.PI + 0.002 + (2 * Math.PI - 0.004) * k / 320;
    circlePoints.push([Math.cos(a), Math.sin(a)]);
  }
  const z0 = [3 / 5, 4 / 5];
  const w0 = map(z0);
  const makePlane = (prefix, rect, moving) => {
    let result;
    s.view(prefix + '-view', { rect, orbit: false, camera: { mode: '2d', yaw: 0, pitch: 0, perspective: 0, height: 4.6, target: [0, 0, 0] } }, v => {
      const scaffold = [];
      scaffold.push(v.line(prefix + '-re-axis', { points: [[-4, 0], [4, 0]], stroke: { color: Color.WHITE, opacity: 0.28 }, strokeWidth: 0.012 }));
      scaffold.push(v.line(prefix + '-im-axis', { points: [[0, -2.3], [0, 2.3]], stroke: { color: Color.WHITE, opacity: 0.28 }, strokeWidth: 0.012 }));
      scaffold.push(v.text(prefix + '-one', { text: '1', position: [1, -0.2], fontSize: 0.22, fill: Color.GREY_A }));
      scaffold.push(v.text(prefix + '-i', { text: 'i', position: [0.17, 1.08], fontSize: 0.22, fill: Color.GREY_A }));
      scaffold.push(v.text(prefix + '-re', { text: 'Re', position: [2.5, -0.2], fontSize: 0.21, fill: Color.GREY_B }));
      scaffold.push(v.text(prefix + '-im', { text: 'Im', position: [0.25, 2.08], fontSize: 0.21, fill: Color.GREY_B }));
      const axes = v.group(prefix + '-scaffold', scaffold);
      const paths = specifications.map(spec => v.path(prefix + '-' + spec.id, {
        d: pathData(spec.points), fill: Color.NONE,
        stroke: { color: spec.color, opacity: 0.55 }, strokeWidth: 0.013,
      }));
      const grid = v.group(prefix + '-grid', paths);
      const circle = v.path(prefix + '-selected-circle', { d: pathData(circlePoints), fill: Color.NONE, stroke: Color.YELLOW, strokeWidth: 0.04 });
      const point = v.circle(prefix + '-point', { position: z0, radius: 0.065, fill: Color.PINK, stroke: Color.BLACK, strokeWidth: 0.016 });
      const pointLabel = v.latex(prefix + '-point-label', { tex: moving ? 'w_0' : 'z_0', fontSize: 0.29, fill: Color.PINK });
      v.attach(pointLabel, point, { offset: [0.3, 0.27, 0] });
      const selection = v.group(prefix + '-selection', [circle, point, pointLabel], { opacity: 0 });
      let pole;
      if (!moving) {
        const crossA = v.line('pole-cross-a', { points: [[-1.07, -0.07], [-0.93, 0.07]], stroke: Color.RED, strokeWidth: 0.028 });
        const crossB = v.line('pole-cross-b', { points: [[-1.07, 0.07], [-0.93, -0.07]], stroke: Color.RED, strokeWidth: 0.028 });
        const label = v.latex('pole-label', { tex: '-1', position: [-1.08, -0.29], fontSize: 0.23, fill: Color.RED });
        pole = v.group('pole', [crossA, crossB, label], { opacity: 0 });
      }
      result = { axes, paths, grid, circle, point, selection, pole };
    });
    return result;
  };
  const left = makePlane('source', [0.04, 0.27, 0.44, 0.46], false);
  const right = makePlane('image', [0.52, 0.27, 0.44, 0.46], true);
  const formula = s.latex('map-formula', { tex: 'w=\\frac{z-1}{z+1}', fontSize: 0.52, position: [0, 2.45] });
  const sourceHeading = s.latex('source-heading', { tex: 'z', position: [0, 2.08], viewportOffset: [-0.24, 0], fontSize: 0.36 });
  const imageHeading = s.latex('image-heading', { tex: 'w', position: [0, 2.08], viewportOffset: [0.24, 0], fontSize: 0.36 });
  const sourceCircleLabel = s.latex('source-circle-label', { tex: '|z|=1', position: [0, -2.15], viewportOffset: [-0.24, 0], fontSize: 0.36, fill: Color.YELLOW, opacity: 0 });
  const sourcePointValue = s.latex('source-point-value', { tex: 'z_0=\\frac{3+4i}{5}', position: [0, -2.67], viewportOffset: [-0.24, 0], fontSize: 0.33, fill: Color.PINK, opacity: 0 });
  const interpolation = s.text('interpolation-label', { text: 'Pointwise interpolation', position: [0, -2.15], viewportOffset: [0.24, 0], fontSize: 0.27, fill: Color.GREY_A, opacity: 0 });
  const poleRule = s.latex('pole-rule', { tex: '-1\\mapsto\\infty', position: [0, -2.67], viewportOffset: [0.24, 0], fontSize: 0.32, fill: Color.RED, opacity: 0 });

  play([formula.fadeIn(), sourceHeading.fadeIn(), imageHeading.fadeIn(), left.axes.fadeIn(), right.axes.fadeIn(), left.grid.fadeIn(), right.grid.fadeIn()], D * 0.06);
  play([left.selection.fadeIn(), right.selection.fadeIn(), left.pole.fadeIn(), sourceCircleLabel.fadeIn(), sourcePointValue.fadeIn(), poleRule.fadeIn()], D * 0.06);
  holdTo(D * 0.18);
  play(interpolation.fadeIn(), D * 0.02);
  const deformation = right.paths.map((path, i) => path.morphTo({ kind: 'path', d: pathData(specifications[i].points.map(map)), fill: Color.NONE }));
  deformation.push(right.circle.morphTo({ kind: 'path', d: pathData(circlePoints.map(map)), fill: Color.NONE }));
  deformation.push(right.point.moveTo(w0));
  play(deformation, D * 0.55);
  play([interpolation.fadeOut(), poleRule.fadeOut()], D * 0.025);
  s.remove(interpolation);
  s.remove(poleRule);
  const imageCircleLabel = s.latex('image-circle-label', { tex: '\\operatorname{Re}w=0', position: [0, -2.15], viewportOffset: [0.24, 0], fontSize: 0.36, fill: Color.YELLOW });
  const imagePointValue = s.latex('image-point-value', { tex: 'w_0=\\frac{i}{2}', position: [0, -2.67], viewportOffset: [0.24, 0], fontSize: 0.33, fill: Color.PINK });
  play([imageCircleLabel.fadeIn(), imagePointValue.fadeIn()], D * 0.025);
  holdTo(D);
});

const __narration=(()=>{const data=JSON.parse("{\"audioAssetId\":\"silent-svd\",\"endMode\":\"hold\",\"durationSec\":20,\"words\":{}}");const get=(id,index)=>{if(!Object.hasOwn(data.words,id))throw new Error('Unknown narration word ID: '+id);return data.words[id][index];};return Object.freeze({audioAssetId:data.audioAssetId,endMode:data.endMode,durationSec:data.durationSec,start:id=>get(id,0),end:id=>get(id,1)});})();
export default scene({ mode: "2d", orbit: false, background: Color.BLACK, audio: __narration.audioAssetId, end: __narration.endMode }, s => {
  const T = __narration.durationSec;
  let cursor = 0;
  const play = (actions, duration) => { s.play(actions, { duration, ease: "smooth" }); cursor += duration; };
  const until = t => { if (t > cursor) { s.wait(t - cursor); cursor = t; } };
  play(s.camera.to2D({ height: 10, target: [0, 0, 0] }), 0);

  // Exact example: A = R(atan(3/4)) diag(2,1) R(-pi/4).
  // Coordinates are mathematical, not measured data.
  const angleV = -Math.PI / 4;
  const angleU = Math.atan2(3, 4);
  const center = [0, -0.55];
  const stretchLocal = p => [1.5 * p[0] + 0.5 * p[1], 0.5 * p[0] + 1.5 * p[1]];
  const formula = s.latex("exact-svd", {
    tex: String.raw`\frac{1}{5\sqrt{2}}\begin{bmatrix}11&5\\2&10\end{bmatrix}=\underbrace{\frac15\begin{bmatrix}4&-3\\3&4\end{bmatrix}}_{U}\underbrace{\begin{bmatrix}2&0\\0&1\end{bmatrix}}_{\Sigma}\underbrace{\frac{1}{\sqrt2}\begin{bmatrix}1&1\\-1&1\end{bmatrix}}_{V^{T}}`,
    position: [0, 2.88], fontSize: 0.43, fill: Color.WHITE
  });

  // Fixed scaffold and a persistent reference copy of the input basis.
  s.line("fixed-x-axis", { points: [[-3.75, center[1]], [3.75, center[1]]], stroke: { color: Color.GREY_B, opacity: 0.35 }, strokeWidth: 0.015 });
  s.line("fixed-y-axis", { points: [[0, -2.95], [0, 1.7]], stroke: { color: Color.GREY_B, opacity: 0.35 }, strokeWidth: 0.015 });
  s.circle("reference-circle", { position: center, radius: 1, fill: Color.NONE, stroke: { color: Color.GREY_B, opacity: 0.5 }, strokeWidth: 0.022 });
  s.arrow("reference-e1", { points: [center, [1, center[1]]], stroke: { color: Color.BLUE, opacity: 0.3 }, strokeWidth: 0.028 });
  s.arrow("reference-e2", { points: [center, [0, center[1] + 1]], stroke: { color: Color.YELLOW, opacity: 0.3 }, strokeWidth: 0.028 });

  const children = [];
  const deforming = [];
  const path = (id, points, style, closed = false) => {
