  const note = s.text('model-status', { text: 'Kinematic model - not torque-integrated', position: [0, -2.95], fontSize: 0.25, fill: Color.GREY_B });
  let rotor, precession, model;
  const metal = { metalness: 0.75, roughness: 0.46 };
