    spinningParts.push(v.cylinder('rotor-hub', { radius: 0.235, height: 0.43, radialSegments: 40, fill: Color.GREY_B, material: metal }));
    for (let i = 0; i < 6; i++) {
      const a = i * Math.PI / 3;
