    const momentum = v.arrow3D('angular-momentum', { points: [[0, 3.4, 0], [0, 4.07, 0]], stroke: Color.BLUE, strokeWidth: 0.04 });
    const lAnchor = v.sphere('momentum-label-anchor', { radius: 0.001, opacity: 0, position: [0, 4.08, 0] });
