    model.line3D('precession-locus-' + i, { points: [[tipRadius * Math.cos(a), tipHeight, -tipRadius * Math.sin(a)], [tipRadius * Math.cos(b), tipHeight, -tipRadius * Math.sin(b)]], stroke: { color: Color.WHITE, opacity: 0.35 }, strokeWidth: 0.014 });
  }
