    tex: '6\\text{ nearest }\\mathrm{Cl}^{-}\\quad\\text{(octahedral)}',
    position: [0, -2.30], fontSize: 0.33, fill: Color.GOLD
  });
  playTo(D * 0.73, [coordination.fadeIn()]);
  // No sites move: the operation is a selection/cutaway, not crystal dynamics.
