  const waitTo = t => { if (t > cursor) { s.wait(t - cursor); cursor = t; } };
  const playFor = (actions, dt) => { s.play(actions, { duration: dt, ease: 'linear' }); cursor += dt; };
  s.play(s.camera.to2D({ height: 10 }), { duration: 0 });

