    v.arrow3D('parameter-y',{points:[[-3.3,-1,-2.6],[-3.3,-1,2.6]],...scaffold});
    v.arrow3D('loss-height',{points:[[-3.3,-1,-2.6],[-3.3,2.4,-2.6]],...scaffold});
