    v.latex('axis-y',{tex:'y',position:[-3.3,-1,2.85],fontSize:0.25,billboard:true});
    v.latex('axis-f',{tex:'F',position:[-3.3,2.66,-2.6],fontSize:0.25,billboard:true});
