    const e = 0.001;
    const hu = (relief(u + e, z) - relief(u - e, z)) / (2 * e);
    const hz = -0.19 + (relief(u, z + e) - relief(u, z - e)) / (2 * e);
    const cx = (center(z + e) - center(z - e)) / (2 * e);
