      { top: 1.25, fill: Color.GREEN_D, secondary: Color.GREEN_E, bump: 0.003 },
      { top: 2.1, fill: Color.GREY_D, secondary: Color.GREY_C, bump: 0.006 },
      { top: Infinity, fill: Color.GREY_B, secondary: Color.GREY_C, bump: 0.006 }
    ];
