  const stepDuration = D * 0.60 / sampleCount;
  for (let i = 0; i < sampleCount; i++) {
    play([marker.moveTo(route[i + 1]), trace[i].fadeIn()], stepDuration, 'linear');
  }
  play(marker.fadeOut(), D * 0.025);
  holdTo(D);
});

