  let boom, stick, bucket, load, stationarySoil = [], cylinders = [];
  s.view('worksite', { rect: [0,0.025,1,0.92], orbit: true, orbitHitTest: 'geometry', camera: { yaw: 0.48, pitch: -0.72, target: [0.45,2.0,0], height: 8.15, distance: 18, perspective: 0.35 } }, v => {
