    bucketParts.push(block('bucket-floor',[0.5,-0.7,0],[1.16,0.13,1.04],Color.GREY_C,'steel'));
    bucketParts.push(block('bucket-back',[-0.05,-0.39,0],[0.16,0.6,1.04],Color.GREY_D,'steel'));
