  function motion(from,to,finish) {
    const start=cursor, span=finish-start, steps=Math.ceil(span/0.1);
    for(let k=1;k<=steps;k++) {
      const u=k/steps, e=u*u*(3-2*u), q=from.map((x,i)=>x+(to[i]-x)*e);
