  stationarySoil.forEach(x=>s.remove(x));
  s.play(load.fadeIn(),{duration:0});
  motion(contact,curled,D*0.53);
  holdTo(D*0.58);
  motion(curled,raised,D*0.82);
  holdTo(D);
});
